// =====================================================================
// SABORES Y RUTAS DE SUCRE - BASE DE DATOS NoSQL DOCUMENTAL (MongoDB)
// Retos NoSQL B y C del Modelo de Negocio 3.
//
// Cómo ejecutarlo (MongoDB Atlas o MongoDB local), desde la terminal
// en la carpeta donde está este archivo:
//   mongosh "CADENA_DE_CONEXION" --file sabores_rutas_sucre_mongodb.js
// Después pueden revisar las colecciones en MongoDB Compass.
//
// Los datos salen de la base MySQL (mismos ids, experiencias, reservas,
// pagos y valoraciones) para que ambas bases sean coherentes.
// El script borra y vuelve a crear la base sabores_rutas_sucre en Mongo.
// =====================================================================

db = db.getSiblingDB("sabores_rutas_sucre");
db.dropDatabase();

function titulo(t) { print("\n==================== " + t + " ===================="); }

// ---------------------------------------------------------------------
// 1. COLECCIONES
// experiencias: catálogo. Cada documento trae embebidos su operador,
//   recursos y programaciones, y un subdocumento "detalles" cuya forma
//   cambia según el tipo de experiencia (senderismo, cata, taller...).
// visitantes: perfil del turista con preferencias opcionales.
// reservas: cada reserva embebe un resumen del visitante y de la
//   experiencia, sus pagos y, si existe, su valoración.
//
// El validador exige solo los campos comunes del negocio; "detalles" es
// libre a propósito para admitir atributos variables.
// ---------------------------------------------------------------------
db.createCollection("experiencias", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["titulo", "categoria", "municipio", "operador", "precio_base_cop", "capacidad_max", "estado"],
      properties: {
        titulo: { bsonType: "string" },
        precio_base_cop: { bsonType: ["int", "double", "long", "decimal"], minimum: 0 },
        capacidad_max: { bsonType: ["int", "long", "double"], minimum: 1 },
        estado: { enum: ["ACTIVA", "INACTIVA", "BORRADOR"] },
        detalles: { bsonType: "object" }
      }
    }
  }
});

db.createCollection("reservas", {
  validator: {
    $jsonSchema: {
      bsonType: "object",
      required: ["visitante", "experiencia", "id_programacion", "cantidad_personas", "estado"],
      properties: {
        cantidad_personas: { bsonType: ["int", "long", "double"], minimum: 1 },
        estado: { enum: ["PENDIENTE", "CONFIRMADA", "COMPLETADA", "CANCELADA"] },
        valoracion: {
          bsonType: "object",
          properties: { estrellas: { bsonType: ["int", "long", "double"], minimum: 1, maximum: 5 } }
        }
      }
    }
  }
});

db.createCollection("visitantes");

