// ---------------------------------------------------------------------
// 3. ÍNDICES (según los patrones de acceso más frecuentes)
// ---------------------------------------------------------------------
db.experiencias.createIndex({ categoria: 1, municipio: 1 });
db.experiencias.createIndex({ "programaciones.fecha": 1 });
db.experiencias.createIndex({ etiquetas: 1 });
db.reservas.createIndex({ "visitante.email": 1, fecha_actividad: -1 });
db.reservas.createIndex({ "experiencia.id_experiencia": 1, estado: 1 });
db.visitantes.createIndex({ email: 1 }, { unique: true });
// Índice de texto en español para búsquedas por palabras clave.
db.experiencias.createIndex(
  { titulo: "text", descripcion: "text", etiquetas: "text" },
  { default_language: "spanish", name: "busqueda_texto" }
);

titulo("Documentos cargados");
printjson({
  experiencias: db.experiencias.countDocuments(),
  visitantes: db.visitantes.countDocuments(),
  reservas: db.reservas.countDocuments()
});

// ---------------------------------------------------------------------
// 4. CONSULTAS (Reto NoSQL B)
// ---------------------------------------------------------------------

// Q1. Experiencias de gastronomía activas en Sincelejo
// Filtro por campos comunes a todos los documentos.
titulo("Q1. Experiencias de gastronomía activas en Sincelejo");
printjson(db.experiencias.find(
  { categoria: "Gastronomía", municipio: "Sincelejo", estado: "ACTIVA" },
  { titulo: 1, precio_base_cop: 1, "detalles.platos": 1, _id: 0 }
).toArray());

// Q2. Senderismo por encima de 500 m s. n. m.
// Consulta sobre atributos que SOLO tienen las experiencias de senderismo.
titulo("Q2. Senderismo por encima de 500 m s. n. m.");
printjson(db.experiencias.find(
  { "detalles.tipo": "senderismo", "detalles.altitud_max_msnm": { $gt: 500 } },
  {
    titulo: 1,
    municipio: 1,
    "detalles.nivel_dificultad": 1,
    "detalles.altitud_max_msnm": 1,
    "detalles.equipo_recomendado": 1,
    _id: 0
  }
).toArray());

// Q3. Experiencias gastronómicas aptas para alérgicos a mariscos
// El campo alergenos solo existe en experiencias con comida; $exists evita traer las demás.
titulo("Q3. Experiencias gastronómicas aptas para alérgicos a mariscos");
printjson(db.experiencias.find(
  { "detalles.alergenos": { $exists: true, $nin: ["mariscos"] }, estado: "ACTIVA" },
  { titulo: 1, municipio: 1, "detalles.alergenos": 1, _id: 0 }
).toArray());

// Q4. Experiencias que ofrecen maridaje
// Atributo exclusivo de las catas.
titulo("Q4. Experiencias que ofrecen maridaje");
printjson(db.experiencias.find(
  { "detalles.maridaje": { $exists: true } },
  { titulo: 1, "detalles.menu_por_tiempos": 1, "detalles.maridaje": 1, _id: 0 }
).toArray());

// Q5. Experiencias que recomiendan botas de caminata
// Búsqueda dentro de un arreglo anidado.
titulo("Q5. Experiencias que recomiendan botas de caminata");
printjson(db.experiencias.find(
  { "detalles.equipo_recomendado": "botas de caminata" },
  { titulo: 1, "detalles.nivel_dificultad": 1, _id: 0 }
).toArray());

// Q6. Solicitud del visitante: 'algo tranquilo de gastronomía tradicional'
// Búsqueda por etiquetas: $all exige que estén todas.
titulo("Q6. Solicitud del visitante: 'algo tranquilo de gastronomía tradicional'");
printjson(db.experiencias.find(
  { etiquetas: { $all: ["gastronomía tradicional", "tranquilo"] }, estado: "ACTIVA" },
  { titulo: 1, municipio: 1, etiquetas: 1, _id: 0 }
).toArray());

// Q7. Próximas salidas con cupos libres (portal web)
// Equivale a la vista v_experiencias_disponibles_web de MySQL.
titulo("Q7. Próximas salidas con cupos libres (portal web)");
printjson(db.experiencias.aggregate(
  [
    { $match: { estado: "ACTIVA" } },
    { $unwind: "$programaciones" },
    {
      $match: {
        "programaciones.fecha": { $gte: new Date() },
        "programaciones.cupos_disponibles": { $gt: 0 },
        "programaciones.estado": "PROGRAMADA"
      }
    },
    {
      $project: {
        _id: 0,
        titulo: 1,
        municipio: 1,
        operador: "$operador.nombre",
        fecha: "$programaciones.fecha",
        cupos_libres: "$programaciones.cupos_disponibles"
      }
    },
    { $sort: { fecha: 1 } },
    { $limit: 10 }
  ]
).toArray());

// Q8. Top 5 experiencias por ingresos
// Suma de reservas no canceladas.
titulo("Q8. Top 5 experiencias por ingresos");
printjson(db.reservas.aggregate(
  [
    { $match: { estado: { $ne: "CANCELADA" } } },
    {
      $group: {
        _id: "$experiencia.titulo",
        reservas: { $sum: 1 },
        personas: { $sum: "$cantidad_personas" },
        ingresos_cop: { $sum: "$monto_total_cop" }
      }
    },
    { $sort: { ingresos_cop: -1 } },
    { $limit: 5 }
  ]
).toArray());

// Q9. Satisfacción promedio por operador
// $lookup une reservas con experiencias para obtener el nombre del operador.
titulo("Q9. Satisfacción promedio por operador");
printjson(db.reservas.aggregate(
  [
    { $match: { valoracion: { $exists: true } } },
    {
      $lookup: {
        from: "experiencias",
        localField: "experiencia.id_experiencia",
        foreignField: "_id",
        as: "exp"
      }
    },
    { $unwind: "$exp" },
    {
      $group: {
        _id: "$exp.operador.nombre",
        promedio_estrellas: { $avg: "$valoracion.estrellas" },
        valoraciones: { $sum: 1 }
      }
    },
    { $sort: { promedio_estrellas: -1 } }
  ]
).toArray());

// Q10. Ocupación por municipio
// Cupos reservados = totales - disponibles, sumados por municipio.
titulo("Q10. Ocupación por municipio");
printjson(db.experiencias.aggregate(
  [
    { $unwind: "$programaciones" },
    { $match: { "programaciones.estado": { $ne: "CANCELADA" } } },
    {
      $group: {
        _id: "$municipio",
        cupos_totales: { $sum: "$programaciones.cupos_totales" },
        cupos_libres: { $sum: "$programaciones.cupos_disponibles" }
      }
    },
    {
      $project: {
        cupos_totales: 1,
        cupos_reservados: { $subtract: ["$cupos_totales", "$cupos_libres"] },
        ocupacion_pct: {
          $round: [
            {
              $multiply: [
                { $divide: [{ $subtract: ["$cupos_totales", "$cupos_libres"] }, "$cupos_totales"] },
                100
              ]
            },
            1
          ]
        }
      }
    },
    { $sort: { ocupacion_pct: -1 } }
  ]
).toArray());

// Q11. Demanda por mes (periodos de mayor actividad)
// Agrupa por año y mes de la actividad.
titulo("Q11. Demanda por mes (periodos de mayor actividad)");
printjson(db.reservas.aggregate(
  [
    { $match: { estado: { $ne: "CANCELADA" } } },
    {
      $group: {
        _id: { anio: { $year: "$fecha_actividad" }, mes: { $month: "$fecha_actividad" } },
        reservas: { $sum: 1 },
        personas: { $sum: "$cantidad_personas" }
      }
    },
    { $sort: { "_id.anio": 1, "_id.mes": 1 } }
  ]
).toArray());

// Q12. Historial completo de un visitante
// Un solo documento por reserva ya trae experiencia, pagos y valoración: sin JOIN.
titulo("Q12. Historial completo de un visitante");
printjson(db.reservas.find(
  { "visitante.email": "juan.atencia@correo.test" },
  {
    "experiencia.titulo": 1,
    fecha_actividad: 1,
    estado: 1,
    "pagos.estado": 1,
    "valoracion.estrellas": 1,
    _id: 0
  }
).sort({ fecha_actividad: -1 }).toArray());

// Q13. Reservas con calificación de 2 o menos (para seguimiento)
// Consulta sobre un subdocumento opcional.
titulo("Q13. Reservas con calificación de 2 o menos (para seguimiento)");
printjson(db.reservas.aggregate(
  [
    { $match: { "valoracion.estrellas": { $lte: 2 } } },
    {
      $project: {
        _id: 0,
        visitante: "$visitante.nombre",
        experiencia: "$experiencia.titulo",
        estrellas: "$valoracion.estrellas",
        comentario: "$valoracion.comentario"
      }
    }
  ]
).toArray());

// Q14. Búsqueda por texto: "pescado fresco cerca del mar"
// Encuentra coincidencias de PALABRAS (pescado, mar). Una frase como
// "plan relajante para comer frente al agua" no coincide con "Pasadía
// ecológico... gastronomía marina" aunque signifique lo mismo: esa es
// la limitación que resuelve la base de datos vectorial (siguiente reto).
titulo("Q14. Búsqueda por texto: pescado fresco cerca del mar");
printjson(db.experiencias.find(
  { $text: { $search: "pescado mar" } },
  { titulo: 1, municipio: 1, puntaje: { $meta: "textScore" }, _id: 0 }
).sort({ puntaje: { $meta: "textScore" } }).limit(5).toArray());

// ---------------------------------------------------------------------
// 5. RETO NoSQL C: CATÁLOGO DINÁMICO SIN CAMBIAR EL ESQUEMA
// Necesidad: los operadores crean tipos de experiencia nuevos con
// atributos propios. En MySQL cada atributo nuevo exige ALTER TABLE
// (columnas que quedan vacías para el resto) o una tabla
// atributo-valor difícil de consultar. En MongoDB basta con guardar
// el documento con sus campos.
// ---------------------------------------------------------------------

// C.1 Nuevo tipo de experiencia (ciclismo) con atributos que no existían.
titulo("C.1 Nuevo tipo de experiencia sin ALTER TABLE");

db.experiencias.insertOne(
  {
    _id: 100,
    titulo: "Ruta en bicicleta por Sincelejo",
    descripcion: "Recorrido urbano en bicicleta por parques y barrios tradicionales de Sincelejo.",
    categoria: "Aventura",
    municipio: "Sincelejo",
    departamento: "Sucre",
    operador: {
      id_operador: 6,
      nombre: "Cocina de la Abuela Sabanera",
      nit: "900200105-4",
      telefono: "3053432734",
      email: "operador05@saboresrutas.test"
    },
    precio_base_cop: 45000,
    duracion_horas: 2.5,
    capacidad_max: 12,
    estado: "BORRADOR",
    etiquetas: ["aventura", "urbano", "deporte"],
    detalles: {
      tipo: "ciclismo",
      distancia_km: 14,
      tipo_bicicleta: "urbana",
      incluye_casco: true,
      nivel_dificultad: "Baja",
      puntos_hidratacion: ["Parque Santander", "Plaza Majagual"]
    },
    programaciones: []
  }
);
printjson(db.experiencias.find({ "detalles.tipo": "ciclismo" }, { titulo: 1, detalles: 1, _id: 0 }).toArray());

// C.2 Agregar atributos nuevos a UNA sola experiencia.
titulo("C.2 Atributos nuevos en una sola experiencia");
db.experiencias.updateOne(
  { _id: 11 },
  { $set: {
      "detalles.temporada_recomendada": "diciembre a abril",
      "detalles.especies_migratorias": ["pato barraquete", "águila pescadora"]
  } }
);
printjson(db.experiencias.findOne({ _id: 11 }, { titulo: 1, detalles: 1, _id: 0 }));

// C.3 Programar una nueva salida: se agrega al arreglo embebido.
titulo("C.3 Nueva salida dentro del documento de la experiencia");

db.experiencias.updateOne(
  { _id: 3 },
  { $push: { programaciones: { id_programacion: 9001, fecha: ISODate("2027-02-06T09:00:00Z"), cupos_totales: 12, cupos_disponibles: 12, estado: "PROGRAMADA" } } }
);
printjson(db.experiencias.findOne({ _id: 3 }, { titulo: 1, programaciones: { $slice: -2 }, _id: 0 }));

// C.4 Una sola consulta responde una pregunta que mezcla tipos distintos:
// "experiencias aptas para niños de 10 años", aunque cada tipo guarde
// la edad mínima de forma diferente (o no la guarde).
titulo("C.4 Aptas para niños de 10 años (atributos heterogéneos)");
printjson(db.experiencias.find(
  { estado: "ACTIVA",
    $or: [
      { "detalles.edad_minima": { $lte: 10 } },
      { "detalles.apto_ninos": true },
      { "detalles.edad_minima": { $exists: false }, "detalles.requiere_saber_nadar": { $ne: true } }
    ] },
  { titulo: 1, "detalles.tipo": 1, "detalles.edad_minima": 1, _id: 0 }
).toArray());

// C.5 El validador sigue protegiendo los datos comunes del negocio:
// este documento no se guarda porque le faltan campos obligatorios.
titulo("C.5 El validador rechaza un documento incompleto");
try {
  db.experiencias.insertOne({ titulo: "Experiencia sin datos", detalles: { tipo: "x" } });
} catch (e) {
  print("Rechazado: " + e.message);
}

print("\nFIN DEL SCRIPT");
